// The no-Docker provider: panva/node-oidc-provider on 127.0.0.1:19000 (dev interactions, PKCE required).
// The package is ESM-only: require() of it needs Node 22.12 or later; on older Node use import.
const Provider = require("oidc-provider").default || require("oidc-provider");
const oidc = new Provider("http://127.0.0.1:19000", {
  clients: [{ client_id: "web-pkce", token_endpoint_auth_method: "none",
              redirect_uris: ["http://127.0.0.1:18081/callback"], grant_types: ["authorization_code", "refresh_token"], response_types: ["code"] }],
  features: { devInteractions: { enabled: true }, introspection: { enabled: true }, revocation: { enabled: true } },
  pkce: { methods: ["S256"], required: () => true },
  findAccount: async (ctx, id) => ({ accountId: id, claims: async () => ({ sub: id, email: `${id}@example.test`, email_verified: true }) }),
});
oidc.listen(19000, "127.0.0.1");
